import os
import json
import threading
from queue import Queue, Empty

import websocket  # websocket-client


class StreamingSpeechToText:
    def __init__(self, api_key=None, language_code="en-US", punctuate=True, model="nova-2"):
        self.api_key = api_key or os.environ.get("ASSEMBLYAI_API_KEY")
        if not self.api_key:
            raise ValueError("Missing AssemblyAI API key. Set ASSEMBLYAI_API_KEY or pass api_key.")

        self.language_code = language_code
        self.punctuate = punctuate
        self.model = model

        self._ws = None
        self._send_queue = Queue()
        self._running = False
        self._transcripts = []

    def _ws_url(self):
        return "wss://api.assemblyai.com/v2/realtime/ws?sample_rate=16000"

    def _on_open(self, ws):
        def run():
            while self._running:
                try:
                    chunk = self._send_queue.get(timeout=0.1)
                except Empty:
                    continue
                if chunk is None:
                    break
                ws.send(chunk, opcode=websocket.ABNF.OPCODE_BINARY)

        threading.Thread(target=run, daemon=True).start()

    def _on_message(self, ws, message):
        data = json.loads(message)
        if data.get("message_type") == "FinalTranscript":
            transcript = data.get("text", "")
            if transcript:
                self._transcripts.append(transcript)

    def _on_error(self, ws, error):
        raise RuntimeError(f"WebSocket error: {error}")

    def _on_close(self, ws, close_status_code, close_msg):
        self._running = False

    def start(self):
        headers = {
            "Authorization": self.api_key,
            "X-AssemblyAI-Language-Code": self.language_code,
            "X-AssemblyAI-Punctuate": "true" if self.punctuate else "false",
            "X-AssemblyAI-Model": self.model,
        }

        self._running = True
        self._ws = websocket.WebSocketApp(
            self._ws_url(),
            header=[f"{k}: {v}" for k, v in headers.items()],
            on_open=self._on_open,
            on_message=self._on_message,
            on_error=self._on_error,
            on_close=self._on_close,
        )
        threading.Thread(target=self._ws.run_forever, daemon=True).start()

    def send_audio(self, audio_chunk: bytes):
        if not self._running:
            raise RuntimeError("Recognizer is not running. Call start() first.")
        self._send_queue.put(audio_chunk)

    def stop(self):
        self._running = False
        self._send_queue.put(None)
        if self._ws:
            try:
                self._ws.close()
            except Exception:
                pass

    def get_transcripts(self):
        return list(self._transcripts)
